#include <bits/stdc++.h>
using namespace std;
const long long MOD = 1000000007LL;
long long pw(long long b, long long e){long long r=1;b%=MOD;while(e){if(e&1)r=r*b%MOD;b=b*b%MOD;e>>=1;}return r;}
int main(){
    long long n, k;
    cin >> n >> k;
    if (k >= n) { cout << pw(2, n) << "\n"; return 0; }
    // answer = sum_{j=0}^{k} C(n, j)
    vector<long long> f(n+1), inv(n+1);
    f[0] = 1;
    for (int i = 1; i <= n; i++) f[i] = f[i-1] * i % MOD;
    inv[n] = pw(f[n], MOD-2);
    for (int i = n; i > 0; i--) inv[i-1] = inv[i] * i % MOD;
    long long ans = 0;
    for (long long j = 0; j <= k; j++) {
        ans = (ans + f[n] * inv[j] % MOD * inv[n-j]) % MOD;
    }
    cout << ans << "\n";
}

