int main(){
    int t; scanf("%d", &t);
    while (t--) {
        int n; scanf("%d", &n);
        vector<int> isB(2*n+1, 0);
        for (int i = 0; i < n; i++) { int x; scanf("%d", &x); isB[x] = 1; }
        // M1: max pairs with b before a (b is min of its pair)
        int open = 0, M1 = 0;
        for (int p = 1; p <= 2*n; p++) {
            if (isB[p]) open++;
            else if (open > 0) { open--; M1++; }
        }
        // M2: max pairs with a before b (a is min of its pair)
        open = 0; int M2 = 0;
        for (int p = 1; p <= 2*n; p++) {
            if (!isB[p]) open++;
            else if (open > 0) { open--; M2++; }
        }
        printf("%d\n", M1 + M2 - n + 1);
    }
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main() {
    int n, m; scanf("%d %d", &n, &m);
    const ll INF = LLONG_MAX / 4;
    vector<vector<ll>> w(n, vector<ll>(n, -1));
    for (int k = 0; k < m; k++) {
        int u, v; ll y; scanf("%d %d %lld", &u, &v, &y);
        w[u-1][v-1] = w[v-1][u-1] = y;          // undirected edge, weight y
    }
    vector<ll> d(n, INF); vector<bool> done(n, false); d[0] = 0;
    for (int it = 0; it < n; it++) {            // O(n^2) Dijkstra
        int u = -1;
        for (int v = 0; v < n; v++) if (!done[v] && d[v] < INF && (u < 0 || d[v] < d[u])) u = v;
        if (u < 0) break;
        done[u] = true;
        for (int v = 0; v < n; v++) if (w[u][v] >= 0 && d[u] + w[u][v] < d[v]) d[v] = d[u] + w[u][v];
    }
    if (d[n-1] >= INF) { puts("inf"); return 0; }
    // distinct distance levels among reachable vertices
    vector<ll> L;
    for (int v = 0; v < n; v++) if (d[v] < INF) L.push_back(d[v]);
    sort(L.begin(), L.end()); L.erase(unique(L.begin(), L.end()), L.end());
    vector<pair<ll, string>> games;
    for (size_t i = 0; i < L.size() && L[i] < d[n-1]; i++) {
        string s(n, '0');
        for (int v = 0; v < n; v++) if (d[v] <= L[i]) s[v] = '1';   // d[v] < INF implied by d<=L
        games.push_back({L[i+1] - L[i], s});
    }
    printf("%lld %d\n", d[n-1], (int)games.size());
    for (auto& [t, s] : games) printf("%s %lld\n", s.c_str(), t);
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        int n; scanf("%d", &n);
        static char A[200005], B[200005];
        scanf("%s", A); scanf("%s", B);
        // f(x,y) = min(Ao(x)+Bo(y), Az(x)+Bz(y)), Ao = ones in prefix, Az = zeros in prefix
        vector<ll> Ao(n + 1, 0), Az(n + 1, 0), Bo(n + 1, 0), Bz(n + 1, 0);
        for (int i = 1; i <= n; i++) {
            Ao[i] = Ao[i-1] + (A[i-1] == '1'); Az[i] = i - Ao[i];
            Bo[i] = Bo[i-1] + (B[i-1] == '1'); Bz[i] = i - Bo[i];
        }
        // pick c0 when D(x) <= E(y), where D = Ao-Az, E = Bz-Bo
        vector<array<ll,3>> ys;              // (E, Bo, Bz) per y
        for (int y = 1; y <= n; y++) ys.push_back({Bz[y] - Bo[y], Bo[y], Bz[y]});
        sort(ys.begin(), ys.end());
        vector<ll> pBo(n + 1, 0), pBz(n + 1, 0);
        for (int k = 0; k < n; k++) { pBo[k+1] = pBo[k] + ys[k][1]; pBz[k+1] = pBz[k] + ys[k][2]; }
        ll total = 0;
        for (int x = 1; x <= n; x++) {
            ll D = Ao[x] - Az[x];
            int idx = 0;                      // count of y with E < D
            int lo = 0, hi = n;
            while (lo < hi) { int mid = (lo + hi) / 2; if (ys[mid][0] < D) lo = mid + 1; else hi = mid; }
            idx = lo;
            total += Az[x] * idx + pBz[idx];                       // E < D: use c1
            total += Ao[x] * (n - idx) + (pBo[n] - pBo[idx]);      // E >= D: use c0
        }
        printf("%lld\n", total);
    }
}

