    int n; scanf("%d", &n);
    vector<int> a(n + 1);
    for (int i = 1; i <= n; i++) scanf("%d", &a[i]);
    vector<int> U, Q;                       // U: unused 1-columns; Q: slot providers (2s and 3s)
    vector<pair<int,int>> cells;            // (height from bottom, column)
    int K = 0;
    for (int i = n; i >= 1; i--) {          // right to left
        if (a[i] == 1) U.push_back(i);
        else if (a[i] == 2) {
            if (U.empty()) { puts("-1"); return 0; }
            int m = U.back(); U.pop_back();
            int h = ++K; cells.push_back({h, i}); cells.push_back({h, m});
            Q.push_back(i);
        } else if (a[i] == 3) {
            if (!Q.empty()) {
                int p = Q.back(); Q.pop_back();
                int h = ++K; cells.push_back({h, i}); cells.push_back({h, p});
                Q.push_back(i);
            } else if (!U.empty()) {
                int m = U.back(); U.pop_back();
                cells.push_back({++K, m});
                int h = ++K; cells.push_back({h, i}); cells.push_back({h, m});
                Q.push_back(i);
            } else { puts("-1"); return 0; }
        }
    }
    for (int m : U) cells.push_back({++K, m});
    printf("%d\n", (int)cells.size());
    for (auto [h, c] : cells) printf("%d %d\n", n + 1 - h, c);
}

