    static char buf[1000005];
    scanf("%s", buf);
    string s(buf); int n = s.size();
    string L, R, mid;
    int l = 0, r = n - 1;
    while (l < r) {
        if (s[l] == s[r]) { L += s[l]; R += s[r]; l++; r--; }
        else if (r - l == 1) { mid = string(1, s[l]); break; }
        else if (s[l+1] == s[r]) l++;            // drop s[l]; next step pairs
        else if (s[r-1] == s[l]) r--;            // drop s[r]; next step pairs
        else { l++; r--; }                        // s[l+1]==s[r-1] is the third letter
    }
    if (l == r) mid = string(1, s[l]);
    string Rrev(R.rbegin(), R.rend());
    string t = L + mid + Rrev;
    if ((int)t.size() < n / 2) { puts("IMPOSSIBLE"); return 0; }
    puts(t.c_str());
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main() {
    int n; scanf("%d", &n);
    vector<ll> p(n + 1, 0);
    for (int i = 1; i <= n; i++) { ll x; scanf("%lld", &x); p[i] = p[i-1] + x; }
    // every segment (prefix pair l < r) grouped by its sum; within a group sorted by r
    vector<tuple<ll,int,int>> seg;                    // (sum, r, l)
    seg.reserve((size_t)n * (n + 1) / 2);
    for (int r = 1; r <= n; r++)
        for (int l = 0; l < r; l++) seg.push_back({p[r] - p[l], r, l});
    sort(seg.begin(), seg.end());
    int best = 0; ll bestSum = 0;
    for (size_t i = 0; i < seg.size(); ) {
        size_t j = i; int cnt = 0, last = 0;          // greedy by earliest end within this sum
        while (j < seg.size() && get<0>(seg[j]) == get<0>(seg[i])) {
            int r = get<1>(seg[j]), l = get<2>(seg[j]);
            if (l >= last) { cnt++; last = r; }
            j++;
        }
        if (cnt > best) { best = cnt; bestSum = get<0>(seg[i]); }
        i = j;
    }
    // rebuild the chosen blocks for bestSum
    vector<pair<int,int>> res; int last = 0;
    vector<pair<int,int>> cand;
    for (int r = 1; r <= n; r++) for (int l = 0; l < r; l++)
        if (p[r] - p[l] == bestSum) cand.push_back({r, l});
    sort(cand.begin(), cand.end());                   // by r ascending
    for (auto [r, l] : cand) if (l >= last) { res.push_back({l + 1, r}); last = r; }
    printf("%d\n", (int)res.size());
    for (auto [a, b] : res) printf("%d %d\n", a, b);
}

