int main() {
    int T; scanf("%d", &T);
    while (T--) {
        int n, m, q; scanf("%d %d %d", &n, &m, &q);
        vector<int> a(n + 2), pos(n + 1), b(m + 1);
        for (int i = 1; i <= n; i++) { scanf("%d", &a[i]); pos[a[i]] = i; }
        vector<set<int>> occ(n + 1);
        for (int i = 1; i <= m; i++) { scanf("%d", &b[i]); occ[b[i]].insert(i); }
        const int INF = m + 1;
        vector<int> f(n + 1, INF);                   // first slide where member x presents
        for (int x = 1; x <= n; x++) if (!occ[x].empty()) f[x] = *occ[x].begin();
        // good iff f[a_1] <= f[a_2] <= ... <= f[a_n]; count violating adjacent pairs
        auto bad = [&](int i) { return i >= 1 && i <= n - 1 && f[a[i]] > f[a[i+1]]; };
        int cntBad = 0;
        for (int i = 1; i <= n - 1; i++) cntBad += bad(i);
        string out;
        out += cntBad == 0 ? "YA\n" : "TIDAK\n";
        while (q--) {
            int s, t; scanf("%d %d", &s, &t);
            int o = b[s];
            if (o != t) {
                set<int> aff;
                int px = pos[o], py = pos[t];
                for (int d : {px - 1, px, py - 1, py}) if (d >= 1 && d <= n - 1) aff.insert(d);
                for (int d : aff) cntBad -= bad(d);
                occ[o].erase(s); occ[t].insert(s); b[s] = t;
                f[o] = occ[o].empty() ? INF : *occ[o].begin();
                f[t] = occ[t].empty() ? INF : *occ[t].begin();
                // pairs touching o or t may change; recompute their status
                for (int d : aff) cntBad += bad(d);
            }
            out += cntBad == 0 ? "YA\n" : "TIDAK\n";
        }
        fputs(out.c_str(), stdout);
    }
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        int n; scanf("%d", &n);
        vector<ll> c(n + 1);
        ll sum = 0;
        for (int i = 1; i <= n; i++) { scanf("%lld", &c[i]); sum += c[i]; }
        ll S = sum / n;                              // every B_k has exactly S ones
        vector<int> A(n + 1, 0), rem(n + 2, 0);
        ll x = S;                                    // ones in prefix i, going from i = n down
        ll cur = 0;                                  // ranges k > i that cover position i
        for (int i = n; i >= 1; i--) {
            cur -= rem[i];
            ll R = c[i] - cur;                       // = (i-1)*A_i + [x_i >= 1]
            if (i >= 2) A[i] = (int)((R - (x >= 1 ? 1 : 0)) / (i - 1));
            else A[1] = (int)x;
            if (x >= 1 && i - x + 1 <= i - 1) {      // sorted prefix i covers positions i-x+1 .. i-1
                ll L = i - x + 1;
                cur += 1;
                rem[L - 1] += 1;
            }
            x -= A[i];                               // x is now ones in prefix i-1
        }
        for (int i = 1; i <= n; i++) printf("%d%c", A[i], i < n ? ' ' : '\n');
    }
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        int n; ll d; scanf("%d %lld", &n, &d);
        vector<ll> a(n + 1, 0);
        for (int i = 1; i <= n; i++) scanf("%lld", &a[i]);
        // g[i] = free days strictly between exam i-1 and exam i (a[0] = 0)
        vector<ll> g(n + 2, 0);
        for (int i = 1; i <= n; i++) g[i] = a[i] - a[i-1] - 1;
        multiset<ll> ms;
        for (int i = 1; i <= n; i++) ms.insert(g[i]);
        ll best = *ms.begin();                          // keep the schedule unchanged
        const ll INF = LLONG_MAX / 4;
        for (int i = 1; i <= n; i++) {                  // remove exam i and re-insert it somewhere
            multiset<ll> L = ms;
            ll T;
            if (i < n) {
                L.erase(L.find(g[i])); L.erase(L.find(g[i+1]));
                L.insert(g[i] + g[i+1] + 1);
                T = d - a[n];
            } else {
                L.erase(L.find(g[n]));
                T = d - a[n-1];
            }
            if (L.empty()) continue;
            ll mn = *L.begin();
            ll mx = *L.rbegin();
            ll others = (L.size() >= 2) ? mn : INF;   // minimum once one copy of the maximum is removed
            if (mx >= 1) best = max(best, min(others, (mx - 1) / 2));   // split an internal gap
            if (T >= 1) best = max(best, min(mn, T - 1));               // place after the last exam
        }
        printf("%lld\n", best);
    }
}

