#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main() {
    int t; scanf("%d", &t);
    // direction vectors v[0..5] = (1,1),(0,1),(-1,0),(-1,-1),(0,-1),(1,0) for costs c1..c6
    const ll vx[6] = {1, 0, -1, -1, 0, 1}, vy[6] = {1, 1, 0, -1, -1, 0};
    while (t--) {
        ll x, y; scanf("%lld %lld", &x, &y);
        ll c[6]; for (int i = 0; i < 6; i++) scanf("%lld", &c[i]);
        for (int pass = 0; pass < 2; pass++)            // v[i-1] + v[i+1] = v[i]: cheaper detour
            for (int i = 0; i < 6; i++)
                c[i] = min(c[i], c[(i + 5) % 6] + c[(i + 1) % 6]);
        ll best = LLONG_MAX;
        for (int i = 0; i < 6; i++) {                   // two adjacent directions i and j = i+1 form a basis
            int j = (i + 1) % 6;
            ll D = vx[i] * vy[j] - vy[i] * vx[j];       // +1 or -1
            ll p = (x * vy[j] - y * vx[j]) * D;         // coefficient of v[i] (D = +-1)
            ll q = (vx[i] * y - vy[i] * x) * D;         // coefficient of v[j]
            if (p >= 0 && q >= 0) best = min(best, p * c[i] + q * c[j]);
        }
        printf("%lld\n", best);
    }
}

#include <bits/stdc++.h>
using namespace std;
const int MAXV = 200000;
int main() {
    int n; scanf("%d", &n);
    vector<int> cnt(MAXV + 1, 0), stamp(MAXV + 1, -1), best(MAXV + 1, 0);
    vector<long long> sum(MAXV + 1, 0);
    vector<int> touched;
    for (int i = 0; i < n; i++) {
        int a; scanf("%d", &a);
        touched.clear();
        for (int j = 0; (a >> j) > 0; j++) {          // halve j times, then double k times
            int y = a >> j;
            for (int k = 0; ((long long)y << k) <= MAXV; k++) {
                int v = y << k, c = j + k;
                if (stamp[v] != i) { stamp[v] = i; best[v] = c; touched.push_back(v); }
                else best[v] = min(best[v], c);
            }
        }
        for (int v : touched) { cnt[v]++; sum[v] += best[v]; }
    }
    long long ans = LLONG_MAX;
    for (int v = 1; v <= MAXV; v++) if (cnt[v] == n) ans = min(ans, sum[v]);
    printf("%lld\n", ans);
}

