#include <bits/stdc++.h>
using namespace std;
int main() {
    int k; scanf("%d", &k);
    static char buf[1000005];
    scanf("%s", buf);                                 // text has no spaces inside; read token-wise below
    string T(buf);
    // read remaining words (text is separated by single spaces)
    while (true) {
        int ch = getchar();
        if (ch == EOF) break;
        if (ch == ' ') { T += ' '; scanf("%s", buf); T += buf; }
    }
    int n = T.size();
    vector<int> cuts;                                 // allowed line ends: after a space or a hyphen, and the end
    for (int i = 1; i <= n; i++) if (T[i-1] == ' ' || T[i-1] == '-' || i == n) cuts.push_back(i);
    auto feasible = [&](int W) {
        int lines = 0;
        int pos = 0;
        int j = 0;
        while (pos < n) {
            // largest cut <= pos + W
            while (j + 1 < (int)cuts.size() && cuts[j+1] <= pos + W) j++;
            if (cuts[j] <= pos || cuts[j] > pos + W) return false;   // no break point fits: a fragment is wider than W
            pos = cuts[j];
            lines++;
            if (lines > k) return false;
        }
        return true;
    };
    int lo = 1, hi = n;
    while (lo < hi) {
        int mid = (lo + hi) / 2;
        if (feasible(mid)) hi = mid; else lo = mid + 1;
    }
    printf("%d\n", lo);
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        int n; scanf("%d", &n);
        vector<int> ca(n), cb(n), nxt(n + 1);
        for (int i = 0; i < n; i++) scanf("%d", &ca[i]);
        for (int i = 0; i < n; i++) scanf("%d", &cb[i]);
        for (int i = 0; i < n; i++) nxt[ca[i]] = cb[i];   // colour permutation: color on tape 1 -> color on tape 2
        vector<bool> seen(n + 1, false);
        long long odd = 0;
        for (int c = 1; c <= n; c++) {
            if (seen[c]) continue;
            int len = 0;
            for (int x = c; !seen[x]; x = nxt[x]) { seen[x] = true; len++; }
            if (len % 2 == 1) odd++;
        }
        long long P = (n - odd) / 2;                       // number of +2 (and of -2) coefficients
        printf("%lld\n", 2 * P * (n - P));
    }
}

