                if (kb == 0) {
                    int s = ch[node][ab ^ 1];
                    if (s != -1) cand = max(cand, mx[s]);
                    node = ch[node][ab];
                } else node = ch[node][ab ^ 1];
            }
            if (node != -1) cand = max(cand, mx[node]);
            if (cand >= 0) best = min(best, j - cand + 1);
            node = 0; mx[0] = j;
            for (int b = B - 1; b >= 0; b--) {
                int bit = (a[j] >> b) & 1;
                if (ch[node][bit] == -1) {
                    ch[node][bit] = (int)ch.size();
                    ch.push_back({-1, -1});
                    mx.push_back(-1);
                }
                node = ch[node][bit];
                mx[node] = j;
            }
        }
        printf("%d\n", best == INT_MAX ? -1 : best);
    }
}

typedef long long ll;
const ll BIG = 1000000000000LL;
bool solve(int n, const vector<bool>& kn, vector<ll>& a, const vector<ll>& c) {
    for (int i = 2; i <= n; i++) if (c[i] < c[i-1]) return false;
    vector<int> inc;
    for (int i = 1; i <= n; i++) if (i == 1 || c[i] > c[i-1]) inc.push_back(i);
    inc.push_back(n + 1);
    ll bprev = 0;
    for (size_t x = 0; x + 1 < inc.size(); x++) {
        int p = inc[x], q = inc[x + 1];
        if (kn[p]) { if (bprev + a[p] != c[p]) return false; }
        else a[p] = c[p] - bprev;
        ll cp = c[p];
        bool hasT = q <= n && kn[q];
        ll T = hasT ? c[q] - a[q] : 0;
        int u1 = -1, u = -1;
        for (int i = p + 1; i < q; i++) if (!kn[i]) { if (u1 < 0) u1 = i; u = i; }
        ll b = cp;
        if (u1 < 0) {                                  // flat run fully known
            for (int i = p + 1; i < q; i++) { b += a[i]; if (b > cp) return false; }
            if (hasT && b != T) return false;
            bprev = b; continue;
        }
        for (int i = p + 1; i < u1; i++) { b += a[i]; if (b > cp) return false; }
        for (int i = u1; i < u; i++) if (!kn[i]) a[i] = -BIG;   // fillers keep the run below c_p
        b = cp;
        for (int i = p + 1; i < u; i++) b += a[i];
        ll run = 0, maxS = 0, bu;
        vector<ll> S(q + 1, 0);
        for (int i = u + 1; i < q; i++) { run += a[i]; S[i] = run; maxS = max(maxS, run); }
        if (hasT) {
            bu = T - run;
            if (bu > cp) return false;
            for (int i = u + 1; i < q; i++) if (bu + S[i] > cp) return false;
        } else bu = cp - max(0LL, maxS);
        a[u] = bu - b;
        bprev = bu + run;
    }
    return true;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main() {
    ll n, k; scanf("%lld %lld", &n, &k);
    ll T = k * (k + 1) / 2;
    if (n < T) { puts("NO"); return 0; }
    ll r = n - T;                                   // extra to distribute: a_i = i + E_i, E nondecreasing
    vector<ll> E(k + 1, 0);                         // 1-based
    if (k == 1) E[1] = r;
    else if (r == k - 1) {
        if (k <= 3) { puts("NO"); return 0; }
        E[k - 1] = 1; E[k] = k - 2;
    } else if (r <= k - 2) {
        ll s = r;                                   // last s positions get 1
        for (ll i = k - s + 1; i <= k; i++) E[i] = 1;
    } else {
        ll c = r / k, s = r % k;
        for (ll i = 1; i <= k; i++) E[i] = c + (i > k - s ? 1 : 0);
    }
    puts("YES");
    for (ll i = 1; i <= k; i++) printf("%lld%c", i + E[i], i < k ? ' ' : '\n');
}

