            ll sum = cnt * (s(l) + s(r)) / 2;                    // arithmetic progression sum
            ll bites = (sum + m - 1) / m;
            return bites <= t;
        };
        if (!ok(l)) { puts("-1"); continue; }
        ll lo = l, hi = l + 2000000;                             // heights exceed t quickly, so r stays small
        while (lo < hi) {
            ll mid = (lo + hi + 1) / 2;
            if (ok(mid)) lo = mid; else hi = mid - 1;
        }
        printf("%lld\n", lo);
    }
