#include <bits/stdc++.h>
using namespace std;
int main() {
    int n; scanf("%d", &n);
    vector<int> a(n - 1);
    bool ok = true;
    for (int i = 0; i < n - 1; i++) {
        int x, y; scanf("%d %d", &x, &y);
        if (y != n) ok = false;                      // every pair must contain the global maximum n
        a[i] = x;
    }
    if (ok) {
        sort(a.begin(), a.end());
        for (int i = 0; i < n - 1 && ok; i++) if (a[i] < i + 1) ok = false;   // Hall-type check
    }
    if (!ok) { puts("NO"); return 0; }
    // build a path n - v1 - v2 - ... - v_{n-1}; the bottom-up prefix maxima equal the sorted values
    vector<int> w(n - 1), used(n, 0);
    int ptr = 1;
    for (int j = 0; j < n - 1; j++) {
        if (j == 0 || a[j] > a[j - 1]) w[j] = a[j];   // a new record: the label itself
        else {
            while (used[ptr]) ptr++;                   // smallest unused label
            w[j] = ptr;
        }
        used[w[j]] = 1;
    }
    puts("YES");
    vector<int> top(w.rbegin(), w.rend());             // top-down chain under the root n
    int prev = n;
    for (int v : top) { printf("%d %d\n", prev, v); prev = v; }
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        int n, k; scanf("%d %d", &n, &k);
        vector<int> a(n + 2, 0), sp(n + 2, 0);
        for (int i = 1; i <= n; i++) scanf("%d", &a[i]);
        vector<int> p(k);
        for (int i = 0; i < k; i++) { scanf("%d", &p[i]); sp[p[i]] = 1; }
        int x = a[p[0]];                              // all special indices hold the same value
        vector<int> d(n + 2, 0);
        for (int i = 1; i <= n; i++) d[i] = a[i] ^ x; // 1 = bit differs from the target x
        // boundaries of blocks of 1s in d: S = positions s with d[s-1] != d[s], s in 1..n+1
        vector<int> before(n + 2, 0);                 // before[s] = number of specials strictly left of s
        for (int s = 1; s <= n + 1; s++) before[s] = before[s-1] + (s - 1 >= 1 ? sp[s-1] : 0);
        vector<int> grp(k + 2, 0);
        long long N = 0;
        for (int s = 1; s <= n + 1; s++) {
            if (d[s-1] != d[s]) { grp[before[s]]++; N++; }
        }
        int maxg = 0;
        for (int g : grp) maxg = max(maxg, g);
        long long ans = max(N / 2, (long long)maxg);
        printf("%lld\n", ans);
    }
}

